  const gap = b => ({ right: b.left - from.right, left: from.left - b.right, down: b.top - from.bottom, up: from.top - b.bottom })[direction];
  const [lo, hi, blo, bhi] = horizontal ? ['top', 'bottom', 'top', 'bottom'] : ['left', 'right', 'left', 'right'];
